insert into public.lessons (id,language_code,level_id,position,title_ar,title_en,summary_ar,summary_en,estimated_minutes) values
('ar-a1-1','ar','A1',1,'التحيات واللباقة','Greetings and politeness','قل مرحباً واشكر واعتذر بأدب.','Say hello, thank people and apologise politely.',8),
('ar-a1-2','ar','A1',2,'التعريف بالنفس','Introducing yourself','قدّم نفسك واسأل عن حال الآخرين.','Introduce yourself and ask how others are.',10),
('ar-a1-3','ar','A1',3,'الأرقام','Numbers','عدّ من 1 إلى 5 وقل 10.','Count from 1 to 5 and say 10.',8),
('ar-a1-4','ar','A1',4,'الألوان','Colours','سمِّ الألوان الأساسية.','Name the basic colours.',8),
('ar-a1-5','ar','A1',5,'العائلة والأصدقاء','Family and friends','تحدّث عن أفراد عائلتك وأصدقائك.','Talk about your family and friends.',8),
('ar-a1-6','ar','A1',6,'الطعام','Food','تعرّف على أسماء الأطعمة اليومية.','Learn the names of everyday foods.',8),
('ar-a1-7','ar','A1',7,'في المقهى','At the café','اطلب مشروباً واطلب الحساب بأدب.','Order a drink and ask for the bill politely.',10),
('ar-a1-8','ar','A1',8,'الوقت','Time','تحدّث عن اليوم وغداً وأمس.','Talk about today, tomorrow and yesterday.',8),
('ar-a1-9','ar','A1',9,'الأماكن','Places','سمِّ الأماكن التي تراها في المدينة.','Name the places you see in a city.',8),
('ar-a1-10','ar','A1',10,'التنقل','Getting around','اسأل عن الاتجاهات وتذكرة السفر.','Ask for directions and a ticket.',10),
('ar-a2-1','ar','A2',1,'أيام الأسبوع','Days of the week','سمِّ أيام العمل وعطلة نهاية الأسبوع.','Name the weekdays and the weekend.',8),
('ar-a2-2','ar','A2',2,'الطقس','The weather','صِف الطقس: شمس ومطر وحرّ وبرد.','Describe the weather: sun, rain, heat and cold.',8),
('ar-a2-3','ar','A2',3,'الجسم والصحة','Body and health','سمِّ أجزاء الجسم وتحدّث مع الطبيب.','Name parts of the body and talk to a doctor.',10),
('ar-a2-4','ar','A2',4,'الملابس والتسوّق','Clothes and shopping','اسأل عن السعر وقل إن كان رخيصاً أو غالياً.','Ask the price and say whether it is cheap or expensive.',10),
('ar-a2-5','ar','A2',5,'في البيت','At home','سمِّ غرف البيت وما فيها.','Name the rooms of a home and what is in them.',8),
('ar-a2-6','ar','A2',6,'العمل والدراسة','Work and study','تحدّث عن عملك ودراستك.','Talk about your work and your studies.',10),
('ar-a2-7','ar','A2',7,'وقت الفراغ','Free time','قل ما تحب أن تفعله في وقت فراغك.','Say what you like doing in your free time.',8),
('ar-a2-8','ar','A2',8,'السفر','Travel','استعد لرحلة: المطار والفندق والقطار.','Get ready for a trip: airport, hotel and train.',10),
('ar-a2-9','ar','A2',9,'أفعال يومية','Everyday verbs','تعلّم أفعالاً تستخدمها كل يوم.','Learn verbs you use every day.',10),
